-- SkillStream production schema (Supabase / PostgreSQL)
create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,name text not null,role text not null default 'student' check(role in ('student','instructor')),created_at timestamptz default now());
create table if not exists courses(id uuid primary key default gen_random_uuid(),instructor_id uuid references profiles(id),title text not null,description text,category text,difficulty text,thumbnail_url text,published boolean default false,created_at timestamptz default now());
create table if not exists modules(id uuid primary key default gen_random_uuid(),course_id uuid references courses(id) on delete cascade,title text not null,position int not null);
create table if not exists lessons(id uuid primary key default gen_random_uuid(),module_id uuid references modules(id) on delete cascade,title text not null,description text,video_url text,duration_seconds int,required_completion numeric default 80,position int not null);
create table if not exists enrollments(id uuid primary key default gen_random_uuid(),course_id uuid references courses(id) on delete cascade,student_id uuid references profiles(id) on delete cascade,enrolled_at timestamptz default now(),unique(course_id,student_id));
create table if not exists video_progress(id uuid primary key default gen_random_uuid(),lesson_id uuid references lessons(id) on delete cascade,student_id uuid references profiles(id) on delete cascade,watched_percent numeric default 0,last_position_seconds int default 0,updated_at timestamptz default now(),unique(lesson_id,student_id));
create table if not exists questions(id uuid primary key default gen_random_uuid(),lesson_id uuid references lessons(id) on delete cascade,question text not null,type text default 'mcq',correct_answer text,explanation text,unlock_after_percent numeric default 80);
create table if not exists question_options(id uuid primary key default gen_random_uuid(),question_id uuid references questions(id) on delete cascade,option_text text not null,position int not null);
create table if not exists question_attempts(id uuid primary key default gen_random_uuid(),question_id uuid references questions(id) on delete cascade,student_id uuid references profiles(id) on delete cascade,selected_answer text,is_correct boolean,attempt_no int default 1,time_taken_seconds int,created_at timestamptz default now());
create table if not exists problems(id uuid primary key default gen_random_uuid(),lesson_id uuid references lessons(id) on delete cascade,title text not null,statement text not null,difficulty text,starter_code text,language text default 'javascript');
create table if not exists test_cases(id uuid primary key default gen_random_uuid(),problem_id uuid references problems(id) on delete cascade,input text,expected_output text,hidden boolean default false);
create table if not exists submissions(id uuid primary key default gen_random_uuid(),problem_id uuid references problems(id) on delete cascade,student_id uuid references profiles(id) on delete cascade,language text,code text,status text,score numeric,execution_time_ms int,created_at timestamptz default now());
create table if not exists notes(id uuid primary key default gen_random_uuid(),lesson_id uuid references lessons(id) on delete cascade,student_id uuid references profiles(id) on delete cascade,content text,timestamp_seconds int,created_at timestamptz default now());
create table if not exists bookmarks(id uuid primary key default gen_random_uuid(),lesson_id uuid references lessons(id) on delete cascade,student_id uuid references profiles(id) on delete cascade,timestamp_seconds int,label text,created_at timestamptz default now());
create table if not exists assessments(id uuid primary key default gen_random_uuid(),course_id uuid references courses(id) on delete cascade,title text not null,type text default 'module',passing_score numeric default 60);
create table if not exists assessment_questions(id uuid primary key default gen_random_uuid(),assessment_id uuid references assessments(id) on delete cascade,question_id uuid references questions(id),problem_id uuid references problems(id),position int not null);
create table if not exists assessment_attempts(id uuid primary key default gen_random_uuid(),assessment_id uuid references assessments(id) on delete cascade,student_id uuid references profiles(id) on delete cascade,score numeric,passed boolean,started_at timestamptz default now(),submitted_at timestamptz);
create table if not exists reviews(id uuid primary key default gen_random_uuid(),course_id uuid references courses(id) on delete cascade,student_id uuid references profiles(id) on delete cascade,rating int check(rating between 1 and 5),review text,created_at timestamptz default now());
create table if not exists achievements(id uuid primary key default gen_random_uuid(),student_id uuid references profiles(id) on delete cascade,kind text,badge text,points int default 0,created_at timestamptz default now());
create table if not exists notifications(id uuid primary key default gen_random_uuid(),student_id uuid references profiles(id) on delete cascade,title text,body text,read boolean default false,created_at timestamptz default now());
create table if not exists ai_insights(id uuid primary key default gen_random_uuid(),student_id uuid references profiles(id) on delete cascade,course_id uuid references courses(id) on delete cascade,insight jsonb,created_at timestamptz default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,name,role) values(new.id,coalesce(new.raw_user_meta_data->>'name',split_part(new.email,'@',1)),coalesce(new.raw_user_meta_data->>'role','student')); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
-- RLS
alter table profiles enable row level security; alter table courses enable row level security; alter table modules enable row level security; alter table lessons enable row level security; alter table enrollments enable row level security; alter table video_progress enable row level security; alter table questions enable row level security; alter table question_options enable row level security; alter table question_attempts enable row level security; alter table problems enable row level security; alter table test_cases enable row level security; alter table submissions enable row level security; alter table notes enable row level security; alter table bookmarks enable row level security; alter table assessments enable row level security; alter table assessment_questions enable row level security; alter table assessment_attempts enable row level security; alter table reviews enable row level security; alter table achievements enable row level security; alter table notifications enable row level security; alter table ai_insights enable row level security;
create policy "public published courses" on courses for select using(published=true);
create policy "students own enrollments" on enrollments for all using(auth.uid()=student_id) with check(auth.uid()=student_id);
create policy "students own progress" on video_progress for all using(auth.uid()=student_id) with check(auth.uid()=student_id);
create policy "students own attempts" on question_attempts for all using(auth.uid()=student_id) with check(auth.uid()=student_id);
create policy "students own submissions" on submissions for all using(auth.uid()=student_id) with check(auth.uid()=student_id);
create policy "students own notes" on notes for all using(auth.uid()=student_id) with check(auth.uid()=student_id);
create policy "students own bookmarks" on bookmarks for all using(auth.uid()=student_id) with check(auth.uid()=student_id);
create policy "students own assessments" on assessment_attempts for all using(auth.uid()=student_id) with check(auth.uid()=student_id);
create policy "students own achievements" on achievements for select using(auth.uid()=student_id);
create policy "students own notifications" on notifications for all using(auth.uid()=student_id) with check(auth.uid()=student_id);
create policy "students own insights" on ai_insights for select using(auth.uid()=student_id);
create policy "published modules" on modules for select using(exists(select 1 from courses c where c.id=course_id and c.published));
create policy "published lessons" on lessons for select using(exists(select 1 from modules m join courses c on c.id=m.course_id where m.id=module_id and c.published));
create policy "published questions" on questions for select using(exists(select 1 from lessons l join modules m on m.id=l.module_id join courses c on c.id=m.course_id where l.id=lesson_id and c.published));
create policy "question options" on question_options for select using(exists(select 1 from questions q where q.id=question_id));
create policy "published problems" on problems for select using(exists(select 1 from lessons l join modules m on m.id=l.module_id join courses c on c.id=m.course_id where l.id=lesson_id and c.published));
create policy "visible tests" on test_cases for select using(hidden=false);
create policy "published assessments" on assessments for select using(exists(select 1 from courses c where c.id=course_id and c.published));
create policy "assessment questions" on assessment_questions for select using(exists(select 1 from assessments a where a.id=assessment_id));
create policy "reviews read" on reviews for select using(true); create policy "own reviews" on reviews for insert with check(auth.uid()=student_id);
